using System.ComponentModel.DataAnnotations; namespace HealthCare_Portal.ViewModels;
public sealed class ConsultationViewModel { [Range(1,long.MaxValue)] public long AppointmentId { get; set; } [StringLength(2000)] public string? Symptoms { get; set; } [StringLength(20)] public string? BloodPressure { get; set; } [Range(0,300)] public decimal? Temperature { get; set; } [Range(0,500)] public decimal? Weight { get; set; } [Range(1,300)] public int? Pulse { get; set; } [StringLength(2000)] public string? Diagnosis { get; set; } [StringLength(4000)] public string? Notes { get; set; } [DataType(DataType.Date)] public DateTime? FollowUpDate { get; set; } }
